package de.lazytv.pro.catalog;import android.view.*;import android.widget.*;import java.util.*;import de.lazytv.pro.R;public class CatalogAdapter extends BaseAdapter{private final List<StreamItem>x=new ArrayList<>();public void set(List<StreamItem>a){x.clear();x.addAll(a);notifyDataSetChanged();}public int getCount(){return x.size();}public StreamItem getItem(int p){return x.get(p);}public long getItemId(int p){return p;}public View getView(int p,View v,ViewGroup g){if(v==null)v=LayoutInflater.from(g.getContext()).inflate(R.layout.item_catalog_stream,g,false);StreamItem i=getItem(p);((TextView)v.findViewById(R.id.stream_name)).setText(i.name);((TextView)v.findViewById(R.id.stream_meta)).setText(i.tvgId==null||i.tvgId.isEmpty()?i.type.name():i.type.name()+" • "+i.tvgId);return v;}}